mapper.select:
select requested.member_id as member_id, coalesce(order_stat.order_count, 0) as order_count, coalesce(order_stat.rent_amount, 0) as rent_amount, coalesce(order_stat.active_order_count, 0) as active_order_count, coalesce(order_stat.completed_order_count, 0) as completed_order_count, coalesce(order_stat.overdue_order_count, 0) as overdue_order_count, coalesce(inventory_stat.total_inventory_quantity, 0) as total_inventory_quantity, coalesce(inventory_stat.available_inventory_quantity, 0) as available_inventory_quantity from (
select #{memberId} as member_id
) requested left join ( select o.member_id, count(1) as order_count, coalesce(sum(o.rent_amount), 0) as rent_amount, sum(case when o.order_status in (20, 25, 30, 40, 45, 70) then 1 else 0 end) as active_order_count, sum(case when o.order_status = 50 then 1 else 0 end) as completed_order_count, sum(case when o.order_status in (60, 65) or cast(o.time_effect_status as char) in ('1', 'overdue') then 1 else 0 end) as overdue_order_count from ry_business.ry_rental_order o where o.is_delete = 0 and o.member_id in
#{memberId}
and o.create_time >= #{beginTime} and o.create_time < #{endTime} group by o.member_id ) order_stat on order_stat.member_id = requested.member_id left join ( select i.member_id, coalesce(sum(i.total_quantity), 0) as total_inventory_quantity, coalesce(sum(i.available_quantity), 0) as available_inventory_quantity from ry_business.ry_rental_merchant_inventory i where i.is_delete = 0 and i.status = 0 and i.member_id in
#{memberId}
group by i.member_id ) inventory_stat on inventory_stat.member_id = requested.member_id order by coalesce(order_stat.order_count, 0) desc, requested.member_id
